"""Original vector cartography, manually digitized from the game's published maps.
No source images are embedded. Approximate affine calibration uses known landmarks.
"""
import json, math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'public/maps'
OUT.mkdir(exist_ok=True)

def solve(a,b):
 a=[row[:]+[v] for row,v in zip(a,b)]
 for i in range(3):
  pivot=max(range(i,3),key=lambda j:abs(a[j][i]));a[i],a[pivot]=a[pivot],a[i]
  v=a[i][i];a[i]=[v2/v for v2 in a[i]]
  for j in range(3):
   if j!=i:
    v=a[j][i];a[j]=[x-v*y for x,y in zip(a[j],a[i])]
 return [a[i][3] for i in range(3)]

def fit(points):
 a=[[sum(([p[0],p[1],1][i])*([p[0],p[1],1][j]) for p in points) for j in range(3)] for i in range(3)]
 xx=solve(a,[sum([p[0],p[1],1][i]*p[2] for p in points) for i in range(3)])
 yy=solve(a,[sum([p[0],p[1],1][i]*p[3] for p in points) for i in range(3)])
 return [xx[0],yy[0],xx[1],yy[1],xx[2],yy[2]]

